parameters.jsonBody:
={{ ({
  input: {
    text: $json.narration
  },
  voice: {
    languageCode: ({
      en: 'en-US',
      pl: 'pl-PL',
      ru: 'ru-RU',
      uk: 'uk-UA'
    })[$json.language_code],
    name: $json.voice_name
  },
  audioConfig: {
    audioEncoding: 'MP3'
  }
}) }}

parameters.jsCode:
const jobId = String($json.job_id ?? '')
  .trim()
  .toLowerCase();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!uuidPattern.test(jobId)) {
  throw new Error(
    'job_id must be a valid UUID'
  );
}

return [
  {
    json: {
      job_id: jobId,
    },
  },
];

const job = $input.first().json;

if (!job.job_exists) {
  throw new Error(`Job ${job.requested_job_id} was not found`);
}

if (
  job.status !== 'processing' ||
  !['script', 'voiceover'].includes(job.current_stage)
) {
  throw new Error(
    `Job ${job.job_id} is not eligible for voiceover: ` +
    `status=${job.status}, current_stage=${job.current_stage}`
  );
}

const supportedLanguages = new Set([
  'en',
  'pl',
  'ru',
  'uk',
]);

if (!supportedLanguages.has(job.language_code)) {
  throw new Error(
    `Unsupported language_code: ${job.language_code}`
  );
}

const requiredScenesByDuration = {
  15: 4,
  30: 8,
  45: 12,
  60: 15,
};

const targetDurationSeconds =
  Number(job.target_duration_seconds);

const requiredSceneCount =
  requiredScenesByDuration[targetDurationSeconds];

if (!requiredSceneCount) {
  throw new Error(
    `Unsupported target_duration_seconds: ${job.target_duration_seconds}`
  );
}

if (!Array.isArray(job.scenes)) {
  throw new Error(
    `Job ${job.job_id} scenes are unavailable`
  );
}

if (
  Number(job.scene_count) !== requiredSceneCount ||
  job.scenes.length !== requiredSceneCount
) {
  throw new Error(
    `Job ${job.job_id} must have exactly ` +
    `${requiredSceneCount} scenes`
  );
}

let pendingSceneCount = 0;
let completedSceneCount = 0;

for (let index = 0; index < job.scenes.length; index++) {
  const scene = job.scenes[index];
  const expectedSceneNumber = index + 1;

  if (Number(scene.scene_number) !== expectedSceneNumber) {
    throw new Error(
      `Invalid scene_number at position ${expectedSceneNumber}: ` +
      `received ${scene.scene_number}`
    );
  }

  if (
    typeof scene.scene_id !== 'string' ||
    scene.scene_id.trim() === ''
  ) {
    throw new Error(
      `Scene ${expectedSceneNumber} is missing scene_id`
    );
  }

  if (
    typeof scene.narration !== 'string' ||
    scene.narration.trim() === ''
  ) {
    throw new Error(
      `Scene ${expectedSceneNumber} has empty narration`
    );
  }

  const hasAudioPath =
    typeof scene.audio_path === 'string' &&
    scene.audio_path.trim() !== '';

  const hasDuration =
    scene.duration_seconds !== null &&
    scene.duration_seconds !== undefined;

  if (hasAudioPath !== hasDuration) {
    throw new Error(
      `Scene ${expectedSceneNumber} has inconsistent audio state`
    );
  }

  if (hasAudioPath) {
    const duration = Number(scene.duration_seconds);

    if (!Number.isFinite(duration) || duration <= 0) {
      throw new Error(
        `Scene ${expectedSceneNumber} has invalid audio duration`
      );
    }

    completedSceneCount++;
  } else {
    pendingSceneCount++;
  }
}

return [
  {
    json: {
      ...job,
      required_scene_count: requiredSceneCount,
      pending_scene_count: pendingSceneCount,
      completed_scene_count: completedSceneCount,
    },
  },
];

const transition = $input.first().json;
const job = $('Require Eligible Voiceover Job').first().json;

if (transition.ready_to_run !== true) {
  throw new Error(
    `Job ${job.job_id} could not enter or resume voiceover stage`
  );
}

if (String(transition.job_id) !== String(job.job_id)) {
  throw new Error(
    'Voiceover transition job_id mismatch'
  );
}

if (
  transition.status !== 'processing' ||
  transition.current_stage !== 'voiceover'
) {
  throw new Error(
    `Unexpected voiceover state: ` +
    `status=${transition.status}, ` +
    `current_stage=${transition.current_stage}`
  );
}

const voiceMap = {
  en: 'en-US-Chirp3-HD-Algenib',
  pl: 'pl-PL-Chirp3-HD-Enceladus',
  ru: 'ru-RU-Wavenet-D',
  uk: 'uk-UA-Chirp3-HD-Enceladus',
};

const voiceName = voiceMap[job.language_code];

if (!voiceName) {
  throw new Error(
    `Unsupported language_code: ${job.language_code}`
  );
}

const pendingScenes = job.scenes.filter((scene) => {
  const hasAudioPath =
    typeof scene.audio_path === 'string' &&
    scene.audio_path.trim() !== '';

  const hasDuration =
    scene.duration_seconds !== null &&
    scene.duration_seconds !== undefined;

  return !hasAudioPath && !hasDuration;
});

if (pendingScenes.length === 0) {
  throw new Error(
    `Job ${job.job_id} has no pending voiceover scenes`
  );
}

return pendingScenes.map((scene) => ({
  json: {
    job_id: job.job_id,
    scene_id: scene.scene_id,
    scene_number: Number(scene.scene_number),
    language_code: job.language_code,
    voice_name: voiceName,
    narration: scene.narration,
  },
}));

parameters.jsonBody:
={{ ({
  job_id: $('Prepare Voiceover Items').item.json.job_id,
  scene_number: $('Prepare Voiceover Items').item.json.scene_number,
  audio_base64: $json.audioContent
}) }}

parameters.jsCode:
const items = $input.all();

if (items.length === 0) {
  throw new Error('No audio persistence results received');
}

const jobIds = new Set();

for (const item of items) {
  const result = item.json;

  if (result.persisted !== true) {
    throw new Error(
      `Audio persistence failed for scene ${result.scene_id}`
    );
  }

  if (
    typeof result.job_id !== 'string' ||
    result.job_id.trim() === ''
  ) {
    throw new Error('Persistence result is missing job_id');
  }

  jobIds.add(result.job_id);
}

if (jobIds.size !== 1) {
  throw new Error(
    `Expected one job_id in persistence batch; received ${jobIds.size}`
  );
}

return [
  {
    json: {
      job_id: [...jobIds][0],
    },
  },
];

const result = $input.first().json;

if (!result.job_exists) {
  throw new Error(
    `Job ${result.job_id} was not found during voiceover completion check`
  );
}

if (
  result.status !== 'processing' ||
  result.current_stage !== 'voiceover'
) {
  throw new Error(
    `Unexpected job state after voiceover: ` +
    `status=${result.status}, current_stage=${result.current_stage}`
  );
}

if (result.all_audio_ready !== true) {
  throw new Error(
    `Voiceover is incomplete for job ${result.job_id}: ` +
    `ready=${result.ready_scene_count}, ` +
    `total=${result.total_scene_count}, ` +
    `required=${result.required_scene_count}, ` +
    `incomplete=${result.incomplete_scene_count}`
  );
}

const targetDurationSeconds = Number(result.target_duration_seconds);
const totalAudioDurationSeconds = Number(result.total_audio_duration_seconds);
const correctionAttempt = Number(result.duration_correction_attempt ?? 0);
const minimumAudioDurationSeconds = targetDurationSeconds * 0.90;
const maximumAudioDurationSeconds = targetDurationSeconds * 1.10;

if (!Number.isFinite(totalAudioDurationSeconds) || totalAudioDurationSeconds <= 0) {
  throw new Error('Voiceover completion check returned invalid total duration');
}

const insideWindow =
  totalAudioDurationSeconds >= minimumAudioDurationSeconds &&
  totalAudioDurationSeconds <= maximumAudioDurationSeconds;

if (insideWindow) {
  return [{
    json: {
      job_id: result.job_id,
      status: result.status,
      current_stage: result.current_stage,
      scene_count: Number(result.total_scene_count),
      target_duration_seconds: targetDurationSeconds,
      total_audio_duration_seconds: totalAudioDurationSeconds,
      voiceover_duration_minimum_seconds: minimumAudioDurationSeconds,
      voiceover_duration_maximum_seconds: maximumAudioDurationSeconds,
      duration_correction_attempt: correctionAttempt,
      needs_duration_correction: false,
      voiceover_complete: true,
    },
  }];
}

if (correctionAttempt >= 1) {
  throw new Error(
    `Voiceover duration ${totalAudioDurationSeconds.toFixed(3)}s remains outside the allowed ${minimumAudioDurationSeconds.toFixed(3)}-${maximumAudioDurationSeconds.toFixed(3)}s window after one pace correction for target ${targetDurationSeconds}s`
  );
}

const speakingRate = totalAudioDurationSeconds / targetDurationSeconds;
const minimumAutomaticRate = 0.80;
const maximumAutomaticRate = 1.25;

if (
  !Number.isFinite(speakingRate) ||
  speakingRate < minimumAutomaticRate ||
  speakingRate > maximumAutomaticRate
) {
  throw new Error(
    `Required pace correction ${speakingRate.toFixed(3)} is outside the automatic quality-safe range ${minimumAutomaticRate.toFixed(2)}-${maximumAutomaticRate.toFixed(2)}`
  );
}

return [{
  json: {
    job_id: result.job_id,
    status: result.status,
    current_stage: result.current_stage,
    scene_count: Number(result.total_scene_count),
    target_duration_seconds: targetDurationSeconds,
    total_audio_duration_seconds: totalAudioDurationSeconds,
    voiceover_duration_minimum_seconds: minimumAudioDurationSeconds,
    voiceover_duration_maximum_seconds: maximumAudioDurationSeconds,
    duration_correction_attempt: correctionAttempt,
    needs_duration_correction: true,
    duration_correction_speaking_rate: Number(speakingRate.toFixed(4)),
    voiceover_complete: false,
  },
}];

const audioContent = $json.audioContent;

if (
  typeof audioContent !== 'string' ||
  audioContent.trim() === ''
) {
  throw new Error(
    'Google TTS response is missing audioContent'
  );
}

return {
  json: {
    ...$json,
    audioContent: audioContent.trim(),
  },
};

const audioPath =
  typeof $json.audio_path === 'string'
    ? $json.audio_path.trim()
    : '';

const durationSeconds =
  Number($json.duration_seconds);

const bytes =
  Number($json.bytes);

if (!audioPath) {
  throw new Error(
    'media-worker response is missing audio_path'
  );
}

if (
  !Number.isFinite(durationSeconds) ||
  durationSeconds <= 0
) {
  throw new Error(
    'media-worker returned invalid duration_seconds'
  );
}

if (
  !Number.isFinite(bytes) ||
  bytes <= 0
) {
  throw new Error(
    'media-worker returned invalid audio byte size'
  );
}

return {
  json: {
    ...$json,
    audio_path: audioPath,
    duration_seconds: durationSeconds,
    bytes,
  },
};

const errorItem =
  $input.first()?.json ?? {};

const job =
  $('Require Eligible Voiceover Job')
    .first()
    .json;

if (
  typeof job.job_id !== 'string' ||
  job.job_id.trim() === ''
) {
  throw new Error(
    'Validated job_id is unavailable while recording voiceover failure'
  );
}

const candidates = [
  errorItem.error?.message,
  errorItem.error?.description,
  errorItem.error,
  errorItem.errorMessage,
  errorItem.errorDescription,
  errorItem.message,
];

let message = candidates.find(
  (value) =>
    typeof value === 'string' &&
    value.trim() !== ''
);

if (!message) {
  try {
    message = JSON.stringify(errorItem);
  } catch {
    message = '';
  }
}

message = String(
  message || 'Unknown voiceover stage failure'
)
  .trim()
  .slice(0, 4000);

return [
  {
    json: {
      job_id: job.job_id,
      last_error: message,
    },
  },
];

const assessment = $input.first().json;
const originalItems = $('Prepare Voiceover Items').all();
const speakingRate = Number(assessment.duration_correction_speaking_rate);

if (!Array.isArray(originalItems) || originalItems.length === 0) {
  throw new Error('Original voiceover items are unavailable for duration correction');
}

if (!Number.isFinite(speakingRate) || speakingRate < 0.80 || speakingRate > 1.25) {
  throw new Error(`Invalid duration correction speaking rate: ${assessment.duration_correction_speaking_rate}`);
}

return originalItems.map((item) => ({
  json: {
    ...item.json,
    speaking_rate: speakingRate,
    duration_correction_attempt: 1,
  },
}));

